/* Enforce strict display for hidden attribute */
[hidden] {
  display: none !important;
}

:root {
  --bg-color: #0f172a;
  --card-bg: #1e293b;
  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --accent-color: #38bdf8;
  --border-color: #334155;
  --error-bg: #450a0a;
  --error-text: #fca5a5;
  --error-border: #991b1b;
  --shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.4), 0 8px 10px -6px rgba(0, 0, 0, 0.4);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  background-color: var(--bg-color);
  color: var(--text-main);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1.25rem;
}

.converter-card {
  background-color: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: 16px;
  box-shadow: var(--shadow);
  width: 100%;
  max-width: 440px;
  padding: 2rem;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.card-header {
  text-align: center;
}

.card-header h1 {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text-main);
  margin-bottom: 0.25rem;
}

.subtitle {
  font-size: 0.9rem;
  color: var(--text-muted);
}

.preview-section {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  align-items: center;
}

.swatch {
  width: 100%;
  height: 120px;
  border-radius: 12px;
  background-color: #000000;
  border: 2px solid var(--border-color);
  transition: background-color 0.15s ease, border-color 0.15s ease;
  box-shadow: inset 0 2px 4px rgba(0, 0, 0, 0.25);
}

.hex-output-container {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 1.25rem;
  font-weight: 600;
}

.hex-label {
  color: var(--text-muted);
  font-size: 1rem;
}

.hex-value {
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", monospace;
  color: var(--accent-color);
  letter-spacing: 0.05em;
}

.error-banner {
  width: 100%;
  text-align: center;
  padding: 0.625rem 1rem;
  background-color: var(--error-bg);
  color: var(--error-text);
  border: 1px solid var(--error-border);
  border-radius: 8px;
  font-size: 0.95rem;
  font-weight: 600;
}

.input-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.875rem;
}

.input-group {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
}

.input-group label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-muted);
}

.input-group input {
  width: 100%;
  padding: 0.625rem 0.5rem;
  font-size: 1.125rem;
  font-weight: 500;
  color: var(--text-main);
  background-color: var(--bg-color);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  text-align: center;
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease, background-color 0.15s ease;
}

.input-group input:hover {
  border-color: var(--text-muted);
}

.input-group input:focus {
  border-color: var(--accent-color);
  box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.25);
}

.input-group input:active {
  background-color: #0c1220;
}

/* Input error styling */
.input-group input.invalid {
  border-color: var(--error-border);
  background-color: #2a1114;
}

.input-group input.invalid:focus {
  box-shadow: 0 0 0 3px rgba(239, 68, 68, 0.25);
}

/* Responsive fallback down to 360px */
@media (max-width: 400px) {
  .converter-card {
    padding: 1.25rem;
  }

  .input-grid {
    grid-template-columns: 1fr;
    gap: 0.75rem;
  }

  .input-group {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
  }

  .input-group label {
    min-width: 90px;
  }

  .input-group input {
    max-width: 120px;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  const redInput = document.getElementById('red-input');
  const greenInput = document.getElementById('green-input');
  const blueInput = document.getElementById('blue-input');
  const swatch = document.getElementById('color-swatch');
  const hexOutput = document.getElementById('hex-code');
  const errorMessage = document.getElementById('error-message');

  const inputs = [redInput, greenInput, blueInput];

  function isValidRGBComponent(valueStr) {
    const trimmed = valueStr.trim();
    if (trimmed === '') return false;
    const num = Number(trimmed);
    return Number.isInteger(num) && num >= 0 && num <= 255;
  }

  function componentToHex(c) {
    const hex = c.toString(16).toUpperCase();
    return hex.padStart(2, '0');
  }

  function updateConverter() {
    const rVal = redInput.value;
    const gVal = greenInput.value;
    const bVal = blueInput.value;

    const isRValid = isValidRGBComponent(rVal);
    const isGValid = isValidRGBComponent(gVal);
    const isBValid = isValidRGBComponent(bVal);

    redInput.classList.toggle('invalid', !isRValid);
    greenInput.classList.toggle('invalid', !isGValid);
    blueInput.classList.toggle('invalid', !isBValid);

    if (isRValid && isGValid && isBValid) {
      const r = parseInt(rVal, 10);
      const g = parseInt(gVal, 10);
      const b = parseInt(bVal, 10);
      const hexCode = `#${componentToHex(r)}${componentToHex(g)}${componentToHex(b)}`;

      hexOutput.textContent = hexCode;
      swatch.style.backgroundColor = hexCode;
      errorMessage.hidden = true;
    } else {
      hexOutput.textContent = 'Invalid value';
      errorMessage.hidden = false;
    }
  }

  inputs.forEach(input => {
    input.addEventListener('input', updateConverter);
    input.addEventListener('change', updateConverter);
  });

  // Initial calculation
  updateConverter();
});
